            if f.exception() is not None:
                step(err=f.exception())
            else:
                step(val=f.result())
        asyncio.ensure_future(res).add_done_callback(done)
    step()
    def cancel():
        if state['cancelled'] or state['finished']:
            return
        state['cancelled'] = True
        step(err='Cancelled', force=True)
    return cancel, fut

