var cancellable = function(generator) {
    let cancelled = false, finished = false;
    let resolveP, rejectP;
    const promise = new Promise((res, rej) => { resolveP = res; rejectP = rej; });
    function step(val, err, force) {
        if (finished || (cancelled && !force)) return;
        let res;
        try {
            res = err !== undefined ? generator.throw(err) : generator.next(val);
        } catch (e) {
            finished = true;
            rejectP(e);
            return;
        }
        if (res.done) {
            finished = true;
            resolveP(res.value);
            return;
        }
        Promise.resolve(res.value).then(
            v => step(v, undefined, false),
            e => step(undefined, e, false)
        );
    }
    step(undefined, undefined, false);
    const cancel = () => {
        if (cancelled || finished) return;
        cancelled = true;
        let res;
        try {
            res = generator.throw("Cancelled");
        } catch (e) {
            finished = true;
            rejectP(e);
            return;
        }
        if (res.done) {
            finished = true;
            resolveP(res.value);
            return;
        }
        Promise.resolve(res.value).then(
            v => step(v, undefined, true),
            e => step(undefined, e, true)
        );
    };
    return [cancel, promise];
};
